quests[45142] = { id = 45142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 012 - Behind Tomb of Sargeras" }
quests[45143] = { id = 45143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Judgment Awaits", description = "Our ongoing offensive within the Broken Shore has drawn the interest of many paladins who wish to fight under your leadership. Some are more worthy than others, but only you can be the judge of that.\n\nThe new recruits are lingering in the camp just outside the chapel, awaiting your judgment.", progress = "Not all are worthy of joining the Silver Hand.", completion = "Your judgment is firm and fair, Highlord.\n\nThese new recruits will learn much under your command.\n\nThough I am beginning to wonder, if my worthiness was tested, would I be found lacking?", objectives = "Use Highlord's Judgment to determine the worth of Silver Hand Recruits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45144] = { id = 45144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 013 - Ruined Temple" }
quests[45145] = { id = 45145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonfang Family Relics", description = "As promised, here is the crescent key that will open my family's lockboxes, though nothing of value remains.\n\nI trust whatever you find you'll deliver to Delas? Our ancestor's things, whatever their worth, should remain in our family.", completion = "I know the name Nerus. He's a distant relative of mine, but why would he hold on to fel trinkets?\n\nThe answer to that question might be found within this scroll, but it appears to be blank.", objectives = "Recover Moonfang family relics from within Shadowfen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45146] = { id = 45146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runic Reading", description = "There is something curious about this scroll. It appears to be an empty page to the untrained eye, but I can see a shimmer of runes appear briefly when I hold it up to the light.\n\nAs with most demonic runes, I will need fel blood to undo the magic that's been used to conceal whatever message is within this scroll.", progress = "I will need to submerge the scroll in demon blood in order for the runes to reveal themselves.", completion = "It should only take a moment for the runes to appear once I apply the purified blood.", objectives = "Collect 10 Fel Blood from demons throughout the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45147] = { id = 45147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felstone Destruction", description = "<Delas' mouth drops open as the scroll falls from her hands and onto the floor.>\n\nThis cannot be... the runes... they detail a pact between the Burning Legion and my ancestors. A dark deal that would grant my ancestors protection from demons in this life, but in return, their spirits would belong to the Legion.\n\nThis fel pendant is an embodiment of the pact, and cannot be removed once worn.\n\nQuickly, {name}. You must use your artifact to destroy that cursed piece of jewelry!", completion = "If you were strong enough to destroy the pendant that bound my spirit to the Burning Legion, then there might be hope for my ancestors.", objectives = "Destroy the Felstone Pendant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45148] = { id = 45148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oath Breaker", description = "Many years ago I made a pact with a man I thought not to be unlike myself. His promise of protection seemed too good to be true, but it was a deal I was desperate to make.\n\nIt wasn't until I had signed in blood that the dreadlord Zorak revealed himself.\n\nAs long as he lives, my ancestors will remain bound to the Burning Legion, allowing our enemies to amass an army of unwilling soldiers.\n\nHead to the Broken Shore and slay Oathbinder Zorak. His death will break the hold he has over my ancestors.", completion = "With Zorak dead, my ancestor's spirits can finally be free of their curse.", objectives = "Head to the Broken Shore and slay Oathbinder Zorak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45149] = { id = 45149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending the Crescent Curse", description = "We must do whatever we can to break the curse that befalls my ancestors. \n\nThe Burning Legion have set up camp within the ruins that house our dead, ready to make good on the dreadful pact that was drafted so long ago.\n\nEach of my ancestor's is burdened with a pendant that binds them to their demonic overlords. It cannot be removed, but as you have shown, with enough power it can be destroyed. \n\nEnd the curse that plagues my ancestors and set their spirits free!", progress = "You are the only one powerful enough to destroy the fel pendants that bind my ancestor's spirits to the Legion.", completion = "What you have done for my family will never be forgotten.\n\nThe spirits of the Moonfang family will forever be in your debt.", objectives = "Free Felbound Spirits in Crescent Ruins by destroying their fel pendants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45150] = { id = 45150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 013 - Fel Tower 003" }
