quests[45158] = { id = 45158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 018 - Crashed Alliance Sea Ship" }
quests[45159] = { id = 45159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cubic Conundrum", description = "<You find a mysterious cube. Its design is unfamiliar, but unmistakably ancient. \n\nThe cube's surface is inlaid with magical runes. Though inert, its properties may be worth investigating.\n\nPerhaps if you show it to Dariness the Learned in Dalaran, she could tell you more about it.>", completion = "<Dariness peers at the artifact you hand her.>\n\nA most interesting design! It reminds me of an ancient curio I read about long ago while still in training. I doubt it could be that though. Such a device has never been found.\n\nHmm, I wonder if it still works. Only one way to find out...", objectives = "Take the Mysterious Cube to Dariness the Learned in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45160] = { id = 45160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cubic Currents", description = "To determine this cube's purpose, we need to power it up. Hmm, I have an idea...\n\nThe Nightborne covet a substance you are no doubt familiar with called ancient mana. Should be just the thing for a relic this old. Gather a sufficient quantity and we'll attempt to get it working.\n\nBe careful in Suramar! It would be a shame if this curious cube were lost and became a memory once more.", completion = "I trust you obtained all the ancient mana we need to infuse the cube?", objectives = "Obtain 300 Ancient Mana from Suramar", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45161] = { id = 45161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1.5 Special - 850 - Special - Brawlers - Fight 01 - Tracking Quest" }
quests[45162] = { id = 45162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Brought the Hammer", description = "Your champions found success in the brawl against the Warhammer Council. Bring this \"token\" to the Brawler's Guild as proof.", completion = "Hey not bad, they beat the Council huh? Sure, they can advance to the next level.", objectives = "Go to the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45163] = { id = 45163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning Up", description = "Your champions return successful. They tell a grand tale of how they really cleaned up against Bill the Janitor.", completion = "You think you guys are tough, beating up a janitor and all? Well ok, I suppose I'll get you into the next fight.", objectives = "Return the Broken Broom Handle to the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45164] = { id = 45164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1.5 Special - 850 - Special - Brawlers - Fight 02 - Tracking Quest" }
