quests[45166] = { id = 45166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 020 - Murloc Beach Hut" }
quests[45167] = { id = 45167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "{name}, we will need to bolster our army by any means necessary to have any hope of driving back the legion. The kvaldir are cursed beyond redemption, but they are fierce warriors and are a resource we should not overlook. They are bound to obey whomever posesses Helya's Horn. You must obtain it. \n\nHer so-called helarjar were tasked with guarding it. You will have to take it from them.", objectives = "Find Helya's Horn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45168] = { id = 45168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 021 - Above Puddle Cave" }
quests[45169] = { id = 45169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 022 - Hub Cliff" }
quests[45170] = { id = 45170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[45171] = { id = 45171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1 Class Hall - Special - PVP - PVP Intro Mission - Tracking Quest" }
quests[45172] = { id = 45172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Battle!", description = "Your champions have returned from exploring the battleground with a report detailing wild adventures and death-defying feats of strength and honor. In these ever shifting battles of conquest, more assistance is always required.\n\nWill you answer the call?", progress = "How are you faring in the battleground?", completion = "Well done!  Battlegrounds are certainly no place for the weak.\n\nWith your success, your champions will now look for more opportunities for you to prove your worth.", objectives = "Join and win in any battleground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45173] = { id = 45173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Times", description = "The conflict continues. As always, your assistance is needed in the great battlegrounds. Join the fray, defeat your enemies, and win glory for your faction.", completion = "Well done!", objectives = "Join and win in any battleground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45174] = { id = 45174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt for Illidan Stormrage", description = "Allari the Souleater, an oracle of the Illidari, has been on the hunt for Illidan's soul for quite some time. She now believes that she has discovered its location and requires your assistance in its recovery.\n\nFind Allari at Illidari Stand in Azsuna and aid her in any way possible.\n\nIf Sargeras truly plans to use Illidan's body as a vessel for his own return then returning Illidan's soul to his body is integral in preventing the dark titan from returning to our world!", completion = "The naaru heard my call? Interesting...\n\nVery well, let's get to work. We've found Illidan's soul - finally - and it's not where we expected it to be held.", objectives = "Seek out Allari the Souleater at Illidari Stand in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45175] = { id = 45175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Prism of the Illidari", description = "Alas, I will not burden you with the location of the master's soul just yet, {name}. First we must craft a soul prism powerful enough to hold the master's boundless chaotic energies.\n\nTo do this I require lingering soul fragments from powerful beings found across this world. Bring me enough and I will craft a soul prism capable of holding the soul of the master - at least long enough to transfer into the naaru.", completion = "The Soul Prism of the Illidari is ready for use.\n\nIllidan's soul was plucked from the Nether - stolen - and taken to the underworld. A place known as Helheim.", objectives = "Claim 5 Lingering Soul Fragments from the final bosses of Legion dungeons.\n\nHigher difficulty dungeons provide a greater chance and quantity of Lingering Soul Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45176] = { id = 45176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of Valor: The Once and Future Lord of Shadows", description = "While tracking the master's physical body proved challenging, we were able to locate it in the Nighthold of Suramar. Our intelligence reports that Gul'dan is making final preparations to the Nightwell in order to use its power to usher the soul of Sargeras into Illidan's body.\n\nThe only way to stop that from happening is to put Illidan's own immortal soul back.\n\nTake the Soul Prism of the Illidari and venture to Helheim. Defeat Helya and use the prism on Illidan's soul! Return it to Light's Heart.", completion = "<Light's Heart illuminates brightly and seemingly consumes the Soul Prism.>", objectives = "Defeat Helya in the Trials of Valor raid and then use the Soul Prism of the Illidari to claim Illidan's Soul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45177] = { id = 45177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nighthold", description = "Illidan's soul rests safely within Light's Heart. Take this vessel and deliver it to Khadgar with the following instructions:\n\nWhen Gul'dan attempts to tear the sky asunder and bring the dark titan into our world, call forth the power of this vessel and release Illidan's soul into his body.\n\nGo now, {name}. We do not have much time. The dark ritual will begin soon.", completion = "I... I will do my best, Battlelord. You will - of course - have to do the hard work and lead the assault on the Nighthold!\n\nFOR AZEROTH!", objectives = "Deliver Light's Heart to Khadgar at the Violet Citadel in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45178] = { id = 45178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contagion Containment" }
quests[45179] = { id = 45179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Win the Crowd", description = "The letter invites you to fight in one of the greatest events in the history of Azeroth. The grand arena battles, where fighters win glory and honor, and everyone will remember their names. Or at least until the next season.", completion = "Congratulations are in order I hear?", objectives = "Fight and win in the arena.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45180] = { id = 45180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Island of War", description = "Your champions return weary and wounded. They bear a banner which, when placed in your hands, gives you a sense of foreboding, but also a surge of battle lust. They report to you of an island named Ashran, where heroes are constantly waging a war. The tides push back and forth, each side feinting and thrusting, always trying to gain the upper hand.\n\nAshran needs your help, will you answer the call?", completion = "Ashran is no place for the faint of heart. You did well.", objectives = "Complete the quests in Ashran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45181] = { id = 45181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1 Class Hall - Special - PVP - PVP Repeated - Battleground - Tracking Quest" }
quests[45182] = { id = 45182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost: The Twisted Twin", description = "I have a request from an old friend, Karam Magespear, to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him.\n\nOriginally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order.\n\nFind Karam in the Legerdemain Lounge and see if you can lend a hand.", completion = "You come from the Kirin Tor? So you'll help me find my brother?", objectives = "Meet with Karam Magespear at the Legerdemain Lounge in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45183] = { id = 45183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1 Class Hall - Special - PVP - PVP Repeated - Ashran - Tracking Quest" }
quests[45184] = { id = 45184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1 Class Hall - Special - PVP - PVP Repeated - Arena - Tracking Quest" }
quests[45185] = { id = 45185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message from the Shadows", description = "I know my brother has been misguided in the past, but I fear that he may have fallen in with an unthinkable evil. He recently began meeting in secret with a dark cult, hidden amongst the people of Dalaran.\n\nI travelled here to try to convince him of the error in his ways, but he would not be shaken from his course. Now, he has disappeared. \n\nWhen I last saw him, Raest was staying in a room upstairs. I was unable to find any clues there, but you might fare better.", progress = "Have you found something?", completion = "A letter? From one of the cultists? \n\nThat could be the lead we need!", objectives = "Search the upper room in the Legerdemain Lounge for a clue to Raest Magespear's location.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45186] = { id = 45186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 023 - Sargeras Tower 001" }
quests[45187] = { id = 45187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets in the Underbelly", description = "So my brother has gone off to perform some ritual with these cultists? That explains why he left, but still not to where...\n\nWait! This letter mentions some of these \"Nethersworn\" cultists seeking reagents in the Underbelly. Perhaps we still may be able to find them if we hurry!", progress = "Any leads, {name}?", completion = "Well, this definitely says... something.", objectives = "Question the Underbelly Lowlifes in the Underbelly to find more information about Raest Magespear's location.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45188] = { id = 45188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wisdom of the Council", description = "I'm sorry, {name}, but I can't make heads nor tails of this. Riddles have never exactly been my strength.\n\nWe should take this cultist's writings to the archmage. Perhaps he could shed some light on this.", completion = "What's this, a cultist's manifesto?  \n\nSo Raest has really gone down a dark path, hasn't he?", objectives = "Bring the Nethersworn Manifesto to Archmage Karlain in the Violet Citadel in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45189] = { id = 45189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 024 - Fel River Rock" }
quests[45190] = { id = 45190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where it's Thinnest", description = "Though I have never heard of this \"Nethersworn\" cult, what this manifesto speaks of can't be good.\n\nI do have a theory, however. The writing speaks of \"the place its skin is thinnest.\" I think they might be referring to the place where the veil between Azeroth and the Twisting Nether is weakest - the Tomb of Sargeras. \n\nWith our forces having established a foothold at the Broken Shore, this would be an opportune time for Raest and his cultist allies to reach the tomb. I would suggest you stop them.", completion = "My brother is here!", objectives = "Meet Karam Magespear at Felbreach Hollow in the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45191] = { id = 45191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 025 - Night Elf Ruins 001" }
quests[45192] = { id = 45192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runes of Rending", description = "My brother and his cultists are engaged in some kind of ritual at the far end of the cave. I tried to intervene, but my brother has left magical wards to block the way.\n\nIf you can find a way past them, we may be able to stop him in time!", progress = "We must not hesitate!", completion = "We're too late, the rift has closed!\n\nWe'll have to find another way to get to him.", objectives = "Bypass the wards in Felbreach Hollow and confront Raest Magespear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45193] = { id = 45193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Step Behind", description = "It looks like Raest is out of our reach, but at least his cultists should prove less of a threat.\n\nWe should return to the Kirin Tor. They should be able to help us plan our next move.", completion = "So Raest escaped? This is unfortunate. \n\nStill, I will rest easier knowing the Nethersworn cultists will no longer skulk in the streets of Dalaran. I thank you for that.\n\nThe Kirin Tor will set out at once to figure out how we can reach Raest in the Twisting Nether. I will send for you when we find a way to reach him.", objectives = "Return to Khadgar in the Violet Citadel in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45198] = { id = 45198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 026 - Fallen Fel Tower" }
