quests[45206] = { id = 45206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overloaded Soulshard" }
quests[45207] = { id = 45207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nightborne Apprentice", description = "I would be happy to introduce you to my new apprentice if you do not mind traveling a bit. She is currently in the field keeping an eye on an enclave of Felborne resistance fighters who have sworn loyalty to the Legion. \n\nAs the first nightborne to join the Tirisgarde, I am sure she is eager to prove her skills!", completion = "I've heard so much about you, Archmage {name}. It is a pleasure to finally meet you!", objectives = "Meet Arcanist Ryanna in the Crimson Thicket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45208] = { id = 45208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[45209] = { id = 45209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Scrying Eyes", description = "Until recently, Ly'leth was sending magical messages to us regularly from within the Nighthold. She took care to hide these messages - only the most vigilant scryers could have detected them.\n\nThey could not be within the palace... too much interference from the Nightwell...\n\nOf course! The Terrace of Enlightenment! The Duskwatch must have set up a listening post there.\n\nCheck the scrying orbs for traces of Ly'leth's messages. We must learn what she was trying to tell us!", completion = "So they did intercept her messages! I hope Ly'leth is okay...\n\nWe must investigate this breach she spoke of immediately!", objectives = "Inspect 4 Duskwatch Scrying Orbs in the Terrace of Enlightenment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
