quests[45238] = { id = 45238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Karazhan: Cubic Cynosure", description = "Drat! The ancient mana doesn't seem to be working. I need to think the problem through, focus and...\n\nWait, that's it! Focus! We need to focus the energy of the ancient mana to activate the cube.\n\nI've heard tell of a mana wyrm in Karazhan with the means to focus its powers. Might be just what we need!\n\nWatch out, though. My sources tell me this wyrm is humongous!", completion = "You've done it! Was the wyrm truly gargantuan? Oh, nevermind, size is relative...\n\nLet us get this focus into the cube and see what it does!", objectives = "Obtain a Mana Focus from the Mana Devourer within Karazhan", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45239] = { id = 45239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cubic Coalescing", description = "Success! The cube's magic has been restored! I'm excited to see what it does!\n\nSince you did all the legwork, you should have the honor of activating it. Care to give it a try?", completion = "<Something about the power coursing through the cube urges you to take it into your possession.>", objectives = "Activate the Mysterious Cube", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45240] = { id = 45240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Preparations", description = "Deathlord, we have uncovered an heirloom of great significance and power. Rimefang's harness has appeared in Icecrown Citadel. We must obtain it, rather than let it fall into the hands of others.\n\nI assume you'd like to retrieve the harness personally? We've sent one of our own, Minerva Ravensorrow, ahead to scout. You've met her before, yes? She has impressed us greatly, and we believe she can become quite powerful under your tutelage.\n\nI will open a death gate for you. It is best you meet her there.", completion = "Deathlord! The vrykul have the harness!", objectives = "Take the Death Gate near Highlord Darion Mograine, then meet Minerva Ravensorrow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45243] = { id = 45243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Daumyr's Wings", completion = "Let's show the Legion true power.", objectives = "Ride Daumyr to the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45244] = { id = 45244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 031 - Cave Underneath Horde Ship" }
