quests[45257] = { id = 45257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 042 - Underwater 003" }
quests[45258] = { id = 45258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 043 - Underwater 004" }
quests[45259] = { id = 45259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 044 - Crashed Alliance Gunship" }
quests[45260] = { id = 45260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Day at a Time", description = "Thank you for coming, outlander. It is good to see you again.\n\nI have a situation in the city that needs your attention, but first... \n\nLet us talk of hope.\n\n<Thalyssra gestures toward the arcan'dor.>\n\nThe fruit of the arcan'dor can truly free my people from the Nightwell. However, it only grows so fast. It will take time to distribute this cure.\n\nI think it only right that you help me pass out the fruit as it is ready. Please take this, and give it to anyone.", progress = "In time, all of the shal'dorei will be free.", completion = "I will ask this of you again, as more fruit is ready.\n\nFor now, we have some disturbing news to discuss.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45261] = { id = 45261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continuing the Cure", description = "Given the events at the Waning Crescent, the refugees here are more eager than ever to receive the gift of the arcan'dor and be free of the Nightwell forever. \n\nFortunately, the tree has borne more fruit. Again, I ask that you honor us by giving this fruit to anyone here in Shal'Aran.\n\nWhen you are finished, we shall discuss further developments within the city. Silgryn reports that Arluelle has proven a fine student, and the two are making progress in evacuating citizens.", progress = "No matter what crises come up, we must stay the course and free my people from their addiction.\n\nWe take it one day at a time.", completion = "Good, now to set our attention to those still suffering within the city.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45262] = { id = 45262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message From Ly'leth", description = "The arcan'dor bears fruit once again. Just in time, too - Ly'leth has sent us a message, and it seems she may have a lead on Vanthir. He is long overdue for this gift, assuming we manage to find him.\n\nGive a fruit to another citizen here in Shal'Aran while I finish decrypting Ly'leth's message.", completion = "There. I certainly hope Ly'leth has good news...", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45263] = { id = 45263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eating Before the Meeting", description = "Having Vanthir around has done much to lift the spirits of the people here. I dare say some have begun to relish their newfound freedom, even if they miss their beloved city.\n\nI will not rest until I can give it back to them.\n\nYou and I have an important meeting to attend. Before we go, let us distribute more of the arcan'dor's fruit. \n\nI want people to know that although I must leave for now, I have not abandoned them.", completion = "Very well, let us go.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45264] = { id = 45264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 045 - South Peak" }
quests[45265] = { id = 45265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding the Rebellion", description = "More nightborne flee Suramar every day to join our cause.\n\nOur ranks are swelling, and with the aid of great heroes like yourself and the armies of the Horde and Alliance, our chances have never been better.\n\nHelp me hand out more fruit of the arcan'dor - each one is a life free from slavish dependence on the Nightwell!\n\nAfterwards, we shall speak on how best to assist our new allies in their siege.", completion = "Good. Now let us see to business at the warfront.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45266] = { id = 45266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A United Front", description = "Our rebel fighters have been armed and morale is high - even the Alliance and Horde elves have ceased their squabbling.\n\nWe are nearly ready to march on the city.\n\nHand out this week's fruit, and then we can begin preparations.", completion = "The time has come.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45267] = { id = 45267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before the Siege", description = "So many years of my life spent studying within the Nighthold... \n\nNever had I considered that I would one day have to fight my way back in.\n\nTime is short. The battle will be upon us soon. \n\nPlease, continue our tradition and feed another refugee the fruit of the arcan'dor.", completion = "Just in time. We are ready to begin.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45268] = { id = 45268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Advisor and the Arcanist", description = "This new First Arcanist appointed by Elisande. This... Andaris. If she is as dangerous as I have heard, then Ly'leth may well be lost.\n\nI am sorry, I should not entertain such thoughts. It is just that we have received a troubling message.\n\nHelp me distribute the latest batch of the arcan'dor fruit, then we will discuss the message.", progress = "Are you ready?", completion = "I am glad we can still cure my people, but... I have troubling news.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45269] = { id = 45269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste of Freedom", description = "We are as ready as we will ever be. Once we put Valtrois' plan into action, we can attack the Sanctum of Order and put an end to Andaris. She will never expect us to have trained our withered against fel magic, and her hubris will be her downfall.\n\nCome, let us feed the people one last time.", progress = "Even if our failure means their doom, they deserve a taste of freedom, no matter how fleeting.", completion = "Very well. Let us begin.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45270] = { id = 45270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 046 - Bundle of Cages 000" }
quests[45271] = { id = 45271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insurrection", description = "First Arcanist Thalyssra has received dark tidings regarding the Nightfallen rebellion and requires your assistance.\n\nJourney to Shal'Aran in Suramar and meet with her.", completion = "Welcome hero. Your arrival could not have been better timed.", objectives = "Speak with First Arcanist Thalyssra in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45272] = { id = 45272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insurrection: Missing Persons", description = "First Arcanist Thalyssra has requested your aid in searching for her missing people.\n\nShe has a lead from a very unexpected ally.\n\nMeet with her at Shal'Aran in Suramar.", completion = "Welcome hero. Your arrival could not have been better timed.", objectives = "Speak with First Arcanist Thalyssra in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45276] = { id = 45276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 047 - Webbed Path" }
quests[45277] = { id = 45277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insurrection: Waxing Crescent", description = "First Arcanist Thalyssra has sent word: there has been communication from Ly'leth. Your help is needed.\n\nJourney to Shal'Aran in Suramar and lend what aid you can.", completion = "You are going to want to hear this.", objectives = "Speak with First Arcanist Thalyssra in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45278] = { id = 45278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insurrection: An Elven Problem", description = "The Alliance and Horde have arrived in Suramar. First Arcanist Thalyssra needs your help in providing an introduction.\n\nMeet with Thalyssra in Shal'Aran.", completion = "It would seem the elves have returned to Suramar.", objectives = "Meet with First Arcanist Thalyssra in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45279] = { id = 45279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 048 - Western Island Tree" }
quests[45280] = { id = 45280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insurrection: Crafting War", description = "Refugees are flooding in to Shal'Aran, and many are willing to fight for Thalyssra's rebel army.\n\nThey need weapons, training and help from anyone who can provide it.\n\nGo to Shal'Aran and lend your assistance.", completion = "This is an unexpected problem, but we have more soldiers than food or weapons.", objectives = "Meet with First Arcanist Thalyssra in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45281] = { id = 45281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insurrection: March on Suramar", description = "First Arcanist Thalyssra has sent word: the time has come to launch our assault on Suramar. The elven armies of the Horde, Alliance, Kirin Tor and Nightfallen are assembled.\n\nThey only await your arrival to begin their assault.\n\nReport to Shal'Aran and meet with First Arcanist Thalyssra and prepare for battle.", completion = "The time for our attack has come. It is time for us to take back Suramar from Elisande and her demonic allies!", objectives = "Meet with First Arcanist Thalyssra in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45282] = { id = 45282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insurrection: Elisande's Retort", description = "The combined forces of the elves stand ready to begin their siege on the gates of the Nighthold.\n\nReport to First Arcanist Thalyssra in Shal'Aran to begin the siege.", completion = "The time for our attack has come. It is time for us to take back Suramar from Elisande and her demonic allies!", objectives = "Meet with First Arcanist Thalyssra in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45283] = { id = 45283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 049 - Behind Purple Ritual" }
quests[45284] = { id = 45284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 050 - Spikes Over Green" }
quests[45285] = { id = 45285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insurrection: As Strong As Our Will", description = "In the wake of Elisande's attack, the need is stronger than ever to add to the ranks of the Nightfallen rebellion.\n\nPlans are in motion that may help with this in an unconventional way.\n\nReport to First Arcanist Thalyssra in Shal'Aran for more details.", completion = "Thank you for coming. Your skills will prove to be invaluable for this next part of our plan.", objectives = "Meet with First Arcanist Thalyssra in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45286] = { id = 45286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 051 - Death Knight Overhang" }
quests[45287] = { id = 45287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insurrection: Breaking the Nighthold", description = "First Arcanist Thalyssra sends word that her forces are ready. It is time for you to lead the attack against the Nighthold.\n\nReport to Shal'Aran in Suramar for details.", completion = "The time for our attack has come. It is time for us to take back Suramar from Elisande and her demonic allies!", objectives = "Meet with First Arcanist Thalyssra in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45288] = { id = 45288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 052 - Green Ritual Chamber" }
quests[45289] = { id = 45289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 053 - Underneath Tomb Bridge" }
quests[45291] = { id = 45291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Karazhan: Book Wyrms", description = "My incorporeal condition has allowed me to enter the tower safely for the first time. I must say, it's a bit of a shambles in there!\n\nI could use some help tackling my cleaning checklist. We should start with the library. All those musty tomes are bound to attract mana wyrms!\n\nPlease shelve any books that have fallen to the floor, or worse, taken flight. And if you find mana wyrms nibbling at the pages... step on them!", progress = "How did it go?", completion = "You were HOW small? Gracious! That must have complicated things.\n\nIt looks like there are more books on the floor than when we started. It's as if the books keep jumping off the shelves or something...\n\nThis is going to be harder than I thought!", objectives = "Clean up the Karazhan Library.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45292] = { id = 45292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Karazhan: Rebooting the Cleaner", description = "The Guardian Medivh created the Curator to watch over Karazhan, but I fear the unit is behaving erratically. Prolonged periods of operation may have caused a malfunction.\n\nPlease go up to the Menagerie and disable the Curator. Also, search the area for a box of spare motivator crystals and return to me.\n\nEven with my basic knowledge I should be able to replace its motivator, and we can enlist the Curator's help in cleaning up the tower.", progress = "Did you find the box of spares?", completion = "The box is empty? Drat!\n\nI may be a mage, but I'll never be able to copy Medivh's motivator crystal enchantment!", objectives = "Disable the Curator and find the Box of Spare Motivator Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45293] = { id = 45293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Karazhan: New Shoes", description = "Thus far my Karazhan cleanup project hasn't exactly been a rousing success. Time to try something new.\n\nNew, as in new shoes... horseshoes, that is! A box of horseshoes was left outside the tower. It's a problem finding a delivery person willing to set foot inside... mortality rates being what they are.\n\nIf you would, grab the crate and take it to Koren in the stables. Just be careful passing Attumen. The huntsman doesn't take kindly to outsiders.", progress = "How did it go?", completion = "Oh dear. My fault entirely!\n\nI should have ensured the horseshoes were in good shape before having you deliver them.\n\nThe humidity out here is a real killer!", objectives = "Deliver the Box of 'New' Horseshoes to Koren the Blacksmith in Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45294] = { id = 45294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Karazhan: High Stress Hiatus", description = "The new plays in the opera house have been well received by everyone... except cast members of the older shows. Egos are bruised and tensions are running high!\n\nRomulo and Julianne are ready to poison each other.\n\nTinhead is rusting with tears over his lack of adoration.\n\nLittle Red's cape was stolen by a disgruntled understudy, who ran off to play chess of all things.\n\nActors, am I right? We need them ready to perform in case the audience demands a revival. Please, help me calm their nerves!", progress = "How did it go?", completion = "I can't believe you found what we needed!\n\nUh, not that I doubt you, it's just... well, this is the first time one of my projects has actually worked out.\n\nAnyway, I think delivering these items to the actors will ease tensions for a while.\n\nThis is a momentous day!", objectives = "Help Darius soothe the old casts egos by finding a Positive Review amongst the audience members to simmer tensions between Romulo and Julianne, stealing a Bouquet of Roses from one of the new acts for Tinhead's vanity and finding where the understudy stashed Little Red's cape in the Chess room.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45295] = { id = 45295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Karazhan: Clearing Out the Cobwebs", description = "I admit it... even as a spirit, I am deathly afraid of spiders. All those legs! Dripping fangs! Sticky webs coming out of their...\n\n<Darius does a squirming sort of shimmy that is uncomfortable to watch.>\n\nI'm sure a world-saving hero like you doesn't mind them, though. Which is good, since a whole brood of spiders has taken over the Servant's Quarters.\n\nYou'll handle this, right? If you don't get them all, they'll keep multiplying.", completion = "You got every single spider, right?\n\nEither way, I'll just check that one off the list. No need to check up on your work.\n\n<Darius makes a squinched-up face.>", objectives = "Clean out spiders from the Servant's Quarters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45296] = { id = 45296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Bones About It", description = "The Charred Bone Fragments still smolder with ancient power. Darius would be extremely interested in examining them and hearing of your defeat of Nightbane.", completion = "Nightbane has been defeated! I'm in awe!\n\nMany years have passed since the blue dragon Arcanagos was slain by the corrupted Medivh. Archmage Alturus sought out the remains of the fallen dragon in an effort to study the Guardian's power. \n\nIn retrospect, maybe not the best idea. \n\nYour help has been invaluable.\n\nI still have a lot of work ahead to clean up Karazhan, but for now I dare ask no more of you. Thank you again for your assistance, {name}.", objectives = "Take the Charred Bone Fragments to Darius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45298] = { id = 45298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 054 - Death Knight Nook" }
