quests[45300] = { id = 45300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 056 - Giant Tree" }
quests[45301] = { id = 45301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Charge", description = "Mardum has been quiet for months. I wonder why the Legion is attacking us now? Could be in retaliation for destroying their battleship on the Broken Shore...\n\nWe had better head down ourselves and save the day, don't you agree?", completion = "Good, you made it.", objectives = "Talk to Kyra Lightblade and choose to fly down to Mardum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45302] = { id = 45302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1.5 Class Hall - Brawlers Missions - Has Completed Any Brawlers Mission with Overmax - Tracking Quest" }
