quests[45304] = { id = 45304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attacking the Darkness", description = "Your champions have returned looking somewhat shaken by their encounter with the Shadowmaster.", completion = "Between you and me I'm glad they won, that guy always creeps me out. Ready for the final challenge?", objectives = "Return to the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
