quests[45312] = { id = 45312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Beat the Ball of Meat", description = "Your champions return with a scrap of bloody, tangled, and quite smelly hair.", completion = "I can't believe you beat him! Meatball was so impressed he now insists he wants to work for you. Hope you don't regret it!", objectives = "Take the scrap of hair to the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
