quests[45315] = { id = 45315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1.5 Class Hall - Brawlers - Intro - Tracking Quest - Has Picked up Quest Item" }
quests[45316] = { id = 45316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stabilizing Suramar", description = "Elisande's plan has backfired. She thought to stamp out our rebellion by making an example of the Waning Crescent. \n\nInstead, she ignited the flame of the shal'dorei better than I ever could.\n\nWe must maintain a cohesive campaign against Elisande and the Legion by fighting them in every corner of Suramar. \n\nShow the people that there is still hope - that there are still heroes willing to fight for them!", progress = "Now is the time for action!", completion = "Thank you, {name}. Every day we come closer to freedom for Suramar.", objectives = "Complete 10 world quests in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45317] = { id = 45317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting on All Fronts", description = "We are nearly ready to siege the gates. Your efforts here have been monumental, {name}.\n\nBut let us not forget that you are also the {class}t. Your forces rely on you to command them. No single person can stand against the Legion.\n\nContinue your duty. Guide the {class}s of Azeroth, and victory will be assured.", completion = "Leadership is a difficult burden, {name}.\n\nWe must often split our attention - be sure to keep the big picture in mind.", objectives = "Complete 5 missions from your Order Hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
