quests[45329] = { id = 45329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Portals", description = "This is a serious invasion, but nothing a Slayer like you can't handle. Time to put those weapons to work!", completion = "That was surprisingly easy...", objectives = "Close 3 Legion portals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45330] = { id = 45330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Party", description = "We will have our work cut out for us finding the missing scouts and Lady S'theno. I suspect that one does not wish to be found.\n\nDo your best, {name}!", completion = "You got most of our scouts out alive. And Lady S'theno appears somewhat chastened, at least. Well done!", objectives = "Find Lady S'theno and 10 Illidari Scouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45331] = { id = 45331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Acherus", description = "You've grown a lot since we last met, {name}. Now that we have the harness, let's see if Mograine has a plan to use it.", completion = "Welcome back, Deathlord. I see you were successful.", objectives = "Return to Highlord Darion Mograine in Acherus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
