quests[45437] = { id = 45437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Urgent Situation", description = "Archmage, {name}! We have an important guest. Please meet me in my chamber when you have a moment.", completion = "I have been unfairly maligned by many. I am glad the Tirisgarde does not fall prey to petty rumors!", objectives = "Find Meryl's visitor in the Hall of the Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45439] = { id = 45439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Invasion of... Murlocs?" }
quests[45440] = { id = 45440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Brewing Situation", description = "Greetings, Grandmaster. I'm an expert at producing tricky brews, and Almai and I have been working with Stormstout Brewery to craft Storm Brew for the order. \n\nIn fact, we have already begun production!\n\nThat calls for a party, don't you think? We brought enough of my prized Celebration Brew for everyone!", progress = "Whew. Celebration brew is..*hic* shtronger than I remembered it to be. *urp*", completion = "Whew. Celebration brew is..*hic* shtronger than I remembered it to be. *urp*", objectives = "Direct the Stormstout Brewers to distribute Celebration Brew to the temple balcony, in front of the Laughing Crane, and near the troop training grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45441] = { id = 45441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adacic Grubs - REWORK", description = "Your request to harvest wood does not seem unreasonable, {name}. There is something you can do for me, too.\n\nThere is a species of moth whose grubs feed on trees. Normally their numbers are too low to cause damage, but once a century they reproduce in overwhelming numbers. \n\nThey have just begun their mass emergence. All of my keepers are fighting the nightmare and cannot be spared. I fear I am unable to protect the forest giants on my own.\n\nWill you stomp the grubs out?", objectives = "Stomp out 50 Adacic Grubs", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45442] = { id = 45442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Felling Well", description = "Let's see... Yseralline Seed for healing, Bruiseweed for curing poison, and Elemental Earth for disease resistance. Oh and just a touch of ground Felwort for attunement. \n\nYes, I think this will counteract the Legion's poison. It will probably taste terrible, but what medicine doesn't?\n\nHurry, Grandmaster {name}. Our most stricken friends don't have much time left.", progress = "Did our Curative Brew work?", completion = "It makes my heart glad to see our order returning to health.", objectives = "Use Blanche's Still and then give the Curative Brew to 8 Fel-Poisoned Initiates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45447] = { id = 45447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turned In Marin's Coin" }
quests[45449] = { id = 45449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alchemist Korlya", description = "The zealots within the Garrison of the Fel are led by Alchemist Korlya. It seems likely that's the Felskorn Brewmaster Blanche observed poisoning our brew.\n\nPlease kill her.", completion = "Thank you. That's one less demon working against us.", objectives = "Kill Alchemist Korlya.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45459] = { id = 45459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storming the Legion", description = "I did my best to fight the demons off, but there were too many even for my skill...\n\nAs I lay dying, I overheard the dreadlord commanding a Felskorn alchemist to contaminate my brew and then return to the Broken Shore. \n\nIf you could acquire some of the poison, I'm sure we can concoct an antidote!", completion = "Good, you made it!", objectives = "Talk to Tak-tak to travel to the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
